[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">

  <!-- Primary Meta Tags -->
  <title>Leap Studio — Your Reinvention and Experience Partner</title>
  <meta name="title" content="Leap Studio — Your Reinvention and Experience Partner">
  <meta name="description" content="A global creative agency that challenges the status quo to create transformative experiences that win hearts and move markets in the eco-digital era.">

  <!-- Canonical URL -->
  <link rel="canonical" href="https://leapstudio.com">

  <!-- Open Graph / Facebook -->
  <meta property="og:type" content="website">
  <meta property="og:url" content="https://leapstudio.com">
  <meta property="og:title" content="Leap Studio — Your Reinvention and Experience Partner">
  <meta property="og:description" content="A global creative agency that challenges the status quo to create transformative experiences.">
  <meta property="og:image" content="https://leapstudio.com/og-image.jpg">

  <!-- Twitter -->
  <meta property="twitter:card" content="summary_large_image">
  <meta property="twitter:url" content="https://leapstudio.com">
  <meta property="twitter:title" content="Leap Studio — Your Reinvention and Experience Partner">
  <meta property="twitter:description" content="A global creative agency that challenges the status quo to create transformative experiences.">
  <meta property="twitter:image" content="https://leapstudio.com/og-image.jpg">

  <!-- Favicon -->
  <link rel="icon" type="image/svg+xml" href="data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' viewBox='0 0 100 100'><rect fill='%230A0A0A' width='100' height='100' rx='20'/><text y='.9em' x='50%' text-anchor='middle' font-size='70' fill='white'>L</text></svg>">

  <!-- Google Fonts -->
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800;900&display=swap" rel="stylesheet">

  <style>
    :root {
      --bg-primary: #0A0A0A;
      --bg-secondary: #111111;
      --bg-card: #161616;
      --bg-card-hover: #1a1a1a;
      --text-primary: #FFFFFF;
      --text-secondary: #A0A0A0;
      --text-muted: #666666;
      --accent-blue: #3B82F6;
      --accent-blue-hover: #2563EB;
      --accent-amber: #F59E0B;
      --border-subtle: #2a2a2a;
      --border-light: #333333;
      --font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    }

    * {
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }

    html {
      scroll-behavior: smooth;
    }

    body {
      font-family: var(--font-family);
      background-color: var(--bg-primary);
      color: var(--text-primary);
      line-height: 1.6;
      overflow-x: hidden;
    }

    a {
      color: inherit;
      text-decoration: none;
    }

    button {
      font-family: inherit;
      cursor: pointer;
      border: none;
      background: none;
    }

    img {
      max-width: 100%;
      display: block;
    }

    /* Navigation */
    .nav {
      position: fixed;
      top: 0;
      left: 0;
      right: 0;
      z-index: 1000;
      background: rgba(10, 10, 10, 0.9);
      backdrop-filter: blur(20px);
      border-bottom: 1px solid var(--border-subtle);
    }

    .nav-container {
      max-width: 1400px;
      margin: 0 auto;
      padding: 0 2rem;
      height: 72px;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .nav-logo {
      font-size: 1.5rem;
      font-weight: 800;
      letter-spacing: -0.02em;
    }

    .nav-links {
      display: flex;
      gap: 2.5rem;
      list-style: none;
    }

    .nav-links a {
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .nav-links a:hover {
      color: var(--text-primary);
    }

    .nav-actions {
      display: flex;
      align-items: center;
      gap: 1rem;
    }

    .lang-selector {
      position: relative;
    }

    .lang-btn {
      display: flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.5rem 1rem;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 8px;
      color: var(--text-primary);
      font-size: 0.875rem;
      font-weight: 500;
      transition: all 0.2s ease;
    }

    .lang-btn:hover {
      background: var(--bg-card-hover);
      border-color: var(--border-light);
    }

    .lang-dropdown {
      position: absolute;
      top: calc(100% + 8px);
      right: 0;
      min-width: 160px;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 12px;
      padding: 0.5rem;
      opacity: 0;
      visibility: hidden;
      transform: translateY(-8px);
      transition: all 0.2s ease;
    }

    .lang-dropdown.active {
      opacity: 1;
      visibility: visible;
      transform: translateY(0);
    }

    .lang-option {
      display: block;
      width: 100%;
      padding: 0.75rem 1rem;
      text-align: left;
      border-radius: 8px;
      font-size: 0.875rem;
      color: var(--text-secondary);
      transition: all 0.2s ease;
    }

    .lang-option:hover {
      background: var(--bg-card-hover);
      color: var(--text-primary);
    }

    .lang-option.active {
      color: var(--accent-blue);
    }

    .mobile-menu-btn {
      display: none;
      width: 40px;
      height: 40px;
      align-items: center;
      justify-content: center;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 8px;
      color: var(--text-primary);
    }

    /* Hero Section */
    .hero {
      min-height: 100vh;
      padding: 120px 2rem 80px;
      display: flex;
      flex-direction: column;
      justify-content: center;
    }

    .hero-container {
      max-width: 1400px;
      margin: 0 auto;
      width: 100%;
    }

    .hero-carousel {
      position: relative;
    }

    .hero-slides {
      position: relative;
      overflow: hidden;
    }

    .hero-slide {
      display: none;
      animation: fadeIn 0.6s ease;
    }

    .hero-slide.active {
      display: block;
    }

    @keyframes fadeIn {
      from { opacity: 0; transform: translateY(20px); }
      to { opacity: 1; transform: translateY(0); }
    }

    .hero-card {
      background: linear-gradient(135deg, var(--bg-card) 0%, var(--bg-secondary) 100%);
      border: 1px solid var(--border-subtle);
      border-radius: 24px;
      padding: 3rem;
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      align-items: center;
    }

    .hero-card-content {
      padding-right: 2rem;
    }

    .hero-tag {
      display: inline-block;
      padding: 0.5rem 1rem;
      background: rgba(59, 130, 246, 0.1);
      border: 1px solid rgba(59, 130, 246, 0.3);
      border-radius: 100px;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 1.5rem;
    }

    .hero-card h2 {
      font-size: 2.5rem;
      font-weight: 800;
      line-height: 1.1;
      letter-spacing: -0.03em;
      margin-bottom: 1rem;
    }

    .hero-card p {
      font-size: 1.125rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 2rem;
    }

    .hero-cta {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 1rem 2rem;
      background: var(--accent-blue);
      color: white;
      font-weight: 600;
      border-radius: 12px;
      transition: all 0.2s ease;
    }

    .hero-cta:hover {
      background: var(--accent-blue-hover);
      transform: translateY(-2px);
    }

    .hero-cta svg {
      transition: transform 0.2s ease;
    }

    .hero-cta:hover svg {
      transform: translateX(4px);
    }

    .hero-visual {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, rgba(59, 130, 246, 0.1) 0%, rgba(245, 158, 11, 0.1) 100%);
      border-radius: 16px;
      display: flex;
      align-items: center;
      justify-content: center;
      overflow: hidden;
    }

    .hero-visual-placeholder {
      width: 100%;
      height: 100%;
      display: flex;
      align-items: center;
      justify-content: center;
      background: repeating-linear-gradient(
        45deg,
        transparent,
        transparent 10px,
        rgba(255,255,255,0.02) 10px,
        rgba(255,255,255,0.02) 20px
      );
    }

    .hero-visual-placeholder svg {
      width: 80px;
      height: 80px;
      opacity: 0.5;
    }

    .hero-nav {
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 1rem;
      margin-top: 2rem;
    }

    .hero-dot {
      width: 12px;
      height: 12px;
      border-radius: 50%;
      background: var(--border-light);
      transition: all 0.3s ease;
      cursor: pointer;
    }

    .hero-dot.active {
      background: var(--accent-blue);
      width: 32px;
      border-radius: 6px;
    }

    .hero-dot:hover:not(.active) {
      background: var(--text-muted);
    }

    .hero-arrows {
      position: absolute;
      top: 50%;
      left: 0;
      right: 0;
      transform: translateY(-50%);
      display: flex;
      justify-content: space-between;
      pointer-events: none;
      padding: 0 1rem;
    }

    .hero-arrow {
      width: 48px;
      height: 48px;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-primary);
      pointer-events: all;
      transition: all 0.2s ease;
      cursor: pointer;
    }

    .hero-arrow:hover {
      background: var(--bg-card-hover);
      border-color: var(--border-light);
    }

    /* Team Section */
    .team {
      padding: 100px 2rem;
      background: var(--bg-secondary);
    }

    .team-container {
      max-width: 1400px;
      margin: 0 auto;
    }

    .section-header {
      text-align: center;
      margin-bottom: 3rem;
    }

    .section-tag {
      display: inline-block;
      padding: 0.5rem 1rem;
      background: rgba(59, 130, 246, 0.1);
      border: 1px solid rgba(59, 130, 246, 0.3);
      border-radius: 100px;
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 1rem;
    }

    .section-title {
      font-size: 3rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 1rem;
    }

    .section-subtitle {
      font-size: 1.125rem;
      color: var(--text-secondary);
      max-width: 600px;
      margin: 0 auto;
    }

    .region-tabs {
      display: flex;
      justify-content: center;
      gap: 0.5rem;
      margin-bottom: 3rem;
      flex-wrap: wrap;
    }

    .region-tab {
      padding: 0.75rem 1.5rem;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 100px;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: all 0.2s ease;
    }

    .region-tab:hover {
      background: var(--bg-card-hover);
      color: var(--text-primary);
    }

    .region-tab.active {
      background: var(--accent-blue);
      border-color: var(--accent-blue);
      color: white;
    }

    .team-carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .team-carousel {
      display: flex;
      gap: 1.5rem;
      transition: transform 0.4s ease;
      padding: 0.5rem;
    }

    .team-region-group {
      display: none;
    }

    .team-region-group.active {
      display: flex;
    }

    .team-card {
      flex: 0 0 320px;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 20px;
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .team-card:hover {
      transform: translateY(-4px);
      border-color: var(--border-light);
    }

    .team-card-image {
      aspect-ratio: 4/5;
      background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-card) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .team-card-image::before {
      content: '';
      position: absolute;
      inset: 0;
      background: repeating-linear-gradient(
        45deg,
        transparent,
        transparent 20px,
        rgba(255,255,255,0.02) 20px,
        rgba(255,255,255,0.02) 40px
      );
    }

    .team-avatar {
      width: 120px;
      height: 120px;
      background: var(--border-subtle);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      font-size: 3rem;
      font-weight: 700;
      color: var(--text-muted);
      z-index: 1;
    }

    .team-card-body {
      padding: 1.5rem;
    }

    .team-quote {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.6;
      font-style: italic;
      margin-bottom: 1.25rem;
    }

    .team-name {
      font-size: 1rem;
      font-weight: 700;
      margin-bottom: 0.25rem;
    }

    .team-title {
      font-size: 0.875rem;
      color: var(--text-secondary);
      margin-bottom: 0.75rem;
    }

    .team-location {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      padding: 0.5rem 1rem;
      background: rgba(59, 130, 246, 0.1);
      border-radius: 100px;
      font-size: 0.8125rem;
      font-weight: 500;
      color: var(--accent-blue);
      transition: all 0.2s ease;
    }

    .team-location:hover {
      background: rgba(59, 130, 246, 0.2);
    }

    .team-carousel-nav {
      display: flex;
      justify-content: center;
      gap: 0.75rem;
      margin-top: 2rem;
    }

    .team-nav-btn {
      width: 44px;
      height: 44px;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-primary);
      transition: all 0.2s ease;
    }

    .team-nav-btn:hover {
      background: var(--bg-card-hover);
      border-color: var(--border-light);
    }

    .team-nav-btn:disabled {
      opacity: 0.3;
      cursor: not-allowed;
    }

    /* Work Section */
    .work {
      padding: 100px 2rem;
    }

    .work-container {
      max-width: 1400px;
      margin: 0 auto;
    }

    .work-carousel-wrapper {
      position: relative;
      overflow: hidden;
    }

    .work-carousel {
      display: flex;
      gap: 1.5rem;
      transition: transform 0.4s ease;
      padding: 0.5rem;
      cursor: grab;
    }

    .work-carousel:active {
      cursor: grabbing;
    }

    .work-card {
      flex: 0 0 400px;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 20px;
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .work-card:hover {
      transform: translateY(-4px);
      border-color: var(--border-light);
    }

    .work-card-image {
      aspect-ratio: 16/10;
      background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-card) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
      position: relative;
      overflow: hidden;
    }

    .work-card-image::before {
      content: '';
      position: absolute;
      inset: 0;
      background: repeating-linear-gradient(
        45deg,
        transparent,
        transparent 20px,
        rgba(255,255,255,0.02) 20px,
        rgba(255,255,255,0.02) 40px
      );
    }

    .work-card-icon {
      width: 60px;
      height: 60px;
      background: var(--border-subtle);
      border-radius: 12px;
      display: flex;
      align-items: center;
      justify-content: center;
      z-index: 1;
    }

    .work-card-body {
      padding: 1.5rem;
    }

    .work-client {
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent-amber);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 0.5rem;
    }

    .work-title {
      font-size: 1.125rem;
      font-weight: 700;
      margin-bottom: 0.75rem;
      line-height: 1.4;
    }

    .work-quote {
      font-size: 0.875rem;
      color: var(--text-secondary);
      line-height: 1.6;
      font-style: italic;
    }

    .work-carousel-nav {
      display: flex;
      justify-content: center;
      gap: 0.75rem;
      margin-top: 2rem;
    }

    /* CTA Banner */
    .cta-banner {
      padding: 100px 2rem;
      background: linear-gradient(135deg, rgba(59, 130, 246, 0.1) 0%, rgba(245, 158, 11, 0.05) 100%);
    }

    .cta-container {
      max-width: 800px;
      margin: 0 auto;
      text-align: center;
    }

    .cta-title {
      font-size: 3rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 1rem;
    }

    .cta-body {
      font-size: 1.25rem;
      color: var(--text-secondary);
      line-height: 1.7;
      margin-bottom: 2rem;
    }

    .cta-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 1.25rem 2.5rem;
      background: var(--accent-blue);
      color: white;
      font-size: 1rem;
      font-weight: 600;
      border-radius: 12px;
      transition: all 0.2s ease;
    }

    .cta-btn:hover {
      background: var(--accent-blue-hover);
      transform: translateY(-2px);
    }

    /* How We Work */
    .how-we-work {
      padding: 100px 2rem;
      background: var(--bg-secondary);
    }

    .how-container {
      max-width: 1000px;
      margin: 0 auto;
      text-align: center;
    }

    .how-title {
      font-size: 2.5rem;
      font-weight: 800;
      letter-spacing: -0.03em;
      margin-bottom: 1.5rem;
    }

    .how-body {
      font-size: 1.25rem;
      color: var(--text-secondary);
      line-height: 1.8;
      margin-bottom: 2.5rem;
      max-width: 800px;
      margin-left: auto;
      margin-right: auto;
    }

    .how-btn {
      display: inline-flex;
      align-items: center;
      gap: 0.75rem;
      padding: 1rem 2rem;
      background: transparent;
      border: 1px solid var(--border-light);
      color: var(--text-primary);
      font-size: 1rem;
      font-weight: 500;
      border-radius: 12px;
      transition: all 0.2s ease;
    }

    .how-btn:hover {
      background: var(--bg-card);
      border-color: var(--text-muted);
    }

    /* Latest Insights */
    .insights {
      padding: 100px 2rem;
    }

    .insights-container {
      max-width: 1400px;
      margin: 0 auto;
    }

    .insights-grid {
      display: grid;
      grid-template-columns: repeat(auto-fill, minmax(300px, 1fr));
      gap: 1.5rem;
    }

    .insight-card {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 16px;
      overflow: hidden;
      transition: all 0.3s ease;
    }

    .insight-card:hover {
      transform: translateY(-4px);
      border-color: var(--border-light);
    }

    .insight-card-image {
      aspect-ratio: 16/9;
      background: linear-gradient(135deg, var(--bg-secondary) 0%, var(--bg-card) 100%);
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .insight-card-icon {
      width: 48px;
      height: 48px;
      background: var(--border-subtle);
      border-radius: 10px;
      display: flex;
      align-items: center;
      justify-content: center;
    }

    .insight-card-body {
      padding: 1.25rem;
    }

    .insight-type {
      font-size: 0.75rem;
      font-weight: 600;
      color: var(--accent-blue);
      text-transform: uppercase;
      letter-spacing: 0.05em;
      margin-bottom: 0.5rem;
    }

    .insight-title {
      font-size: 1rem;
      font-weight: 600;
      line-height: 1.4;
      margin-bottom: 1rem;
    }

    .insight-link {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.875rem;
      font-weight: 500;
      color: var(--accent-blue);
      transition: gap 0.2s ease;
    }

    .insight-link:hover {
      gap: 0.75rem;
    }

    /* Principles */
    .principles {
      padding: 100px 2rem;
      background: var(--bg-secondary);
    }

    .principles-container {
      max-width: 1200px;
      margin: 0 auto;
    }

    .principles-grid {
      display: grid;
      grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
      gap: 1.5rem;
    }

    .principle-card {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 20px;
      padding: 2rem;
      transition: all 0.3s ease;
    }

    .principle-card:hover {
      border-color: var(--border-light);
    }

    .principle-number {
      font-size: 0.75rem;
      font-weight: 700;
      color: var(--accent-blue);
      margin-bottom: 1rem;
    }

    .principle-title {
      font-size: 1.25rem;
      font-weight: 700;
      margin-bottom: 0.75rem;
    }

    .principle-text {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* Footer */
    .footer {
      padding: 80px 2rem 40px;
      border-top: 1px solid var(--border-subtle);
    }

    .footer-container {
      max-width: 1400px;
      margin: 0 auto;
    }

    .footer-top {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      margin-bottom: 4rem;
    }

    .footer-cta {
      padding: 2rem;
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 16px;
    }

    .footer-cta-text {
      font-size: 1rem;
      color: var(--text-secondary);
      margin-bottom: 1rem;
    }

    .footer-cta-link {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-size: 0.9375rem;
      font-weight: 600;
      color: var(--accent-blue);
      transition: gap 0.2s ease;
    }

    .footer-cta-link:hover {
      gap: 0.75rem;
    }

    .footer-links {
      display: flex;
      gap: 2rem;
      margin-bottom: 3rem;
    }

    .footer-links a {
      font-size: 0.875rem;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .footer-links a:hover {
      color: var(--text-primary);
    }

    .footer-bottom {
      display: flex;
      justify-content: space-between;
      align-items: center;
      flex-wrap: wrap;
      gap: 1rem;
      padding-top: 2rem;
      border-top: 1px solid var(--border-subtle);
    }

    .footer-legal {
      display: flex;
      gap: 1.5rem;
      flex-wrap: wrap;
    }

    .footer-legal a {
      font-size: 0.8125rem;
      color: var(--text-muted);
      transition: color 0.2s ease;
    }

    .footer-legal a:hover {
      color: var(--text-secondary);
    }

    .footer-copyright {
      font-size: 0.8125rem;
      color: var(--text-muted);
    }

    /* Cookie Banner */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      z-index: 1001;
      background: var(--bg-card);
      border-top: 1px solid var(--border-subtle);
      padding: 1.5rem 2rem;
      transform: translateY(100%);
      transition: transform 0.3s ease;
    }

    .cookie-banner.active {
      transform: translateY(0);
    }

    .cookie-container {
      max-width: 1400px;
      margin: 0 auto;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 2rem;
      flex-wrap: wrap;
    }

    .cookie-text {
      font-size: 0.9375rem;
      color: var(--text-secondary);
      flex: 1;
      min-width: 300px;
    }

    .cookie-actions {
      display: flex;
      gap: 1rem;
      flex-wrap: wrap;
    }

    .cookie-btn {
      padding: 0.75rem 1.5rem;
      font-size: 0.875rem;
      font-weight: 500;
      border-radius: 8px;
      transition: all 0.2s ease;
    }

    .cookie-btn-decline {
      background: transparent;
      border: 1px solid var(--border-light);
      color: var(--text-secondary);
    }

    .cookie-btn-decline:hover {
      background: var(--bg-secondary);
      color: var(--text-primary);
    }

    .cookie-btn-settings {
      background: transparent;
      border: 1px solid var(--border-light);
      color: var(--text-primary);
    }

    .cookie-btn-settings:hover {
      background: var(--bg-secondary);
    }

    .cookie-btn-accept {
      background: var(--accent-blue);
      border: 1px solid var(--accent-blue);
      color: white;
    }

    .cookie-btn-accept:hover {
      background: var(--accent-blue-hover);
    }

    /* Cookie Modal */
    .cookie-modal {
      position: fixed;
      inset: 0;
      z-index: 1002;
      background: rgba(0, 0, 0, 0.8);
      display: flex;
      align-items: center;
      justify-content: center;
      opacity: 0;
      visibility: hidden;
      transition: all 0.3s ease;
    }

    .cookie-modal.active {
      opacity: 1;
      visibility: visible;
    }

    .cookie-modal-content {
      background: var(--bg-card);
      border: 1px solid var(--border-subtle);
      border-radius: 20px;
      max-width: 500px;
      width: 90%;
      max-height: 80vh;
      overflow-y: auto;
      padding: 2rem;
      transform: scale(0.95);
      transition: transform 0.3s ease;
    }

    .cookie-modal.active .cookie-modal-content {
      transform: scale(1);
    }

    .cookie-modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 1.5rem;
    }

    .cookie-modal-title {
      font-size: 1.25rem;
      font-weight: 700;
    }

    .cookie-modal-close {
      width: 36px;
      height: 36px;
      background: var(--bg-secondary);
      border: 1px solid var(--border-subtle);
      border-radius: 8px;
      display: flex;
      align-items: center;
      justify-content: center;
      color: var(--text-secondary);
      transition: all 0.2s ease;
    }

    .cookie-modal-close:hover {
      background: var(--bg-card-hover);
      color: var(--text-primary);
    }

    .cookie-category {
      padding: 1rem 0;
      border-bottom: 1px solid var(--border-subtle);
    }

    .cookie-category:last-child {
      border-bottom: none;
    }

    .cookie-category-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      margin-bottom: 0.5rem;
    }

    .cookie-category-title {
      font-size: 0.9375rem;
      font-weight: 600;
    }

    .cookie-category-desc {
      font-size: 0.8125rem;
      color: var(--text-secondary);
    }

    .cookie-toggle {
      width: 44px;
      height: 24px;
      background: var(--border-light);
      border-radius: 12px;
      position: relative;
      cursor: pointer;
      transition: background 0.2s ease;
    }

    .cookie-toggle.active {
      background: var(--accent-blue);
    }

    .cookie-toggle::after {
      content: '';
      position: absolute;
      top: 2px;
      left: 2px;
      width: 20px;
      height: 20px;
      background: white;
      border-radius: 50%;
      transition: transform 0.2s ease;
    }

    .cookie-toggle.active::after {
      transform: translateX(20px);
    }

    .cookie-modal-footer {
      margin-top: 1.5rem;
      display: flex;
      justify-content: flex-end;
    }

    /* Mobile Menu */
    .mobile-menu {
      position: fixed;
      top: 72px;
      left: 0;
      right: 0;
      bottom: 0;
      background: var(--bg-primary);
      z-index: 999;
      padding: 2rem;
      transform: translateX(100%);
      transition: transform 0.3s ease;
    }

    .mobile-menu.active {
