    }

    .mobile-menu-links {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 1rem;
    }

    .mobile-menu-links a {
      font-size: 1.25rem;
      font-weight: 500;
      color: var(--text-secondary);
      transition: color 0.2s ease;
    }

    .mobile-menu-links a:hover {
      color: var(--text-primary);
    }

    /* Responsive */
